1	//! SEA Forge spec-to-code pipeline (spec-full §7.8, §10.7, M5).
2	//!
3	//! Deterministic stage chaining, generated-zone guard, proof classification,
4	//! and DomainForge projections. The pipeline runs as ordinary governed work —
5	//! no separate engine. This crate provides the pure logic; the CLI wires it
6	//! into the case-run lifecycle.
7	
8	#![forbid(unsafe_code)]
9	
10	use std::collections::BTreeMap;
11	
12	use sea_forge_core::{
13	    errors::ForgeError,
14	    types::{
15	        ProjectionKind, ProjectionRecord, ProjectionStatus, ProjectionValidation,
16	        ProofClassification, SpecPipelineRun, SpecPipelineStage, StageFile, StageKind, StageStatus,
17	    },
18	};
19	use sea_forge_ledger::types::hash_canonical;
20	use sha2::{Digest, Sha256};
21	
22	// ── Stage hashing ──
23	
24	/// Compute the content hash of a single stage.
25	/// Hash covers: stage_id, kind, inputs, outputs, command, status.
26	/// Excludes quarantine_ref and settlement_basis (they are governance metadata, not content).
27	pub fn compute_stage_hash(stage: &SpecPipelineStage) -> Result<String, ForgeError> {
28	    let canonical = serde_json::json!({
29	        "stage_id": stage.stage_id,
30	        "kind": stage.kind,
31	        "inputs": stage.inputs,
32	        "outputs": stage.outputs,
33	        "command": stage.command,
34	        "status": stage.status,
35	    });
36	    let bytes = serde_json::to_vec(&canonical)?;
37	    Ok(format!("sha256:{:x}", Sha256::digest(&bytes)))
38	}
39	
40	/// Compute the chain hash over all stages in order.
41	/// Each stage's hash includes the prior stage's hash, forming a linked chain.
42	pub fn compute_chain_hash(stages: &[SpecPipelineStage]) -> Result<String, ForgeError> {
43	    let mut prior_hash = String::new();
44	    let mut hasher = Sha256::new();
45	    for stage in stages {
46	        let stage_hash = compute_stage_hash(stage)?;
47	        hasher.update(stage_hash.as_bytes());
48	        hasher.update(prior_hash.as_bytes());
49	        prior_hash = format!("{:x}", hasher.clone().finalize());
50	        hasher = Sha256::new();
51	    }
52	    Ok(format!("sha256:{prior_hash}"))
53	}
54	
55	// ── Stage ordering ──
56	
57	/// The canonical stage order per §10.7.
58	const CANONICAL_ORDER: &[StageKind] = &[
59	    StageKind::Adr,
60	    StageKind::Prd,
61	    StageKind::Sds,
62	    StageKind::Sea,
63	    StageKind::Ast,
64	    StageKind::Ir,
65	    StageKind::Manifest,
66	    StageKind::GeneratedContract,
67	    StageKind::SemanticFixture,
68	    StageKind::LastMileAdapter,
69	    StageKind::RuntimeWiring,
70	    StageKind::AcceptanceProof,
71	];
72	
73	/// Validate that stages follow the canonical order and that a later stage
74	/// only starts if all prior accepted stages validate by hash.
75	pub fn validate_stage_order(stages: &[SpecPipelineStage]) -> Result<(), ForgeError> {
76	    let mut last_ordinal: usize = 0;
77	    for stage in stages {
78	        let ordinal = CANONICAL_ORDER
79	            .iter()
80	            .position(|k| k == &stage.kind)
81	            .ok_or_else(|| {
82	                ForgeError::Input(format!(
83	                    "spec_pipeline_error: unknown stage kind {:?}",
84	                    stage.kind
85	                ))
86	            })?;
87	        if ordinal < last_ordinal {
88	            return Err(ForgeError::Input(format!(
89	                "spec_pipeline_error: stage {:?} appears after stage at position {last_ordinal}",
90	                stage.kind
91	            )));
92	        }
93	        last_ordinal = ordinal;
94	    }
95	    Ok(())
96	}
97	
98	// ── Proof classification ──
99	
100	/// Compute the proof classification ceiling based on accepted stages.
101	///
102	/// - `authority-only`: no generated outputs claimed.
103	/// - `generated-contract`: regeneration passed, no runtime path.
104	/// - `focused-slice` or stronger: last_mile + runtime + acceptance all accepted.
105	pub fn compute_proof_classification(stages: &[SpecPipelineStage]) -> ProofClassification {
106	    let has_generated = stages.iter().any(|s| {
107	        s.status == StageStatus::Accepted
108	            && matches!(
109	                s.kind,
110	                StageKind::GeneratedContract
111	                    | StageKind::Ast
112	                    | StageKind::Ir
113	                    | StageKind::Manifest
114	                    | StageKind::SemanticFixture
115	            )
116	    });
117	    let has_last_mile = stages
118	        .iter()
119	        .any(|s| s.status == StageStatus::Accepted && s.kind == StageKind::LastMileAdapter);
120	    let has_runtime = stages
121	        .iter()
122	        .any(|s| s.status == StageStatus::Accepted && s.kind == StageKind::RuntimeWiring);
123	    let has_acceptance = stages
124	        .iter()
125	        .any(|s| s.status == StageStatus::Accepted && s.kind == StageKind::AcceptanceProof);
126	
127	    if has_last_mile && has_runtime && has_acceptance {
128	        ProofClassification::FocusedSlice
129	    } else if has_generated {
130	        ProofClassification::GeneratedContract
131	    } else {
132	        ProofClassification::AuthorityOnly
133	    }
134	}
135	
136	// ── Quarantine ──
137	
138	/// Quarantine a failed stage: set status, write quarantine ref.
139	/// The quarantine file is `{workspace}/quarantine/{stage_id}.jsonl` with
140	/// `{record, score, evidence_ref}` per §10.7/§7.6 pattern.
141	pub fn quarantine_stage(stage: &mut SpecPipelineStage, reason: &str) -> Result<(), ForgeError> {
142	    stage.status = StageStatus::Quarantined;
143	    stage.quarantine_ref = Some(format!("quarantine/{}.json", stage.stage_id));
144	    stage
145	        .settlement_basis
146	        .push(format!("stage_quarantined:{reason}"));
147	    Ok(())
148	}
149	
150	// ── Generated-zone guard ──
151	
152	/// Check if a path is in a generated zone (read-only per §10.7).
153	pub fn is_generated_zone(path: &str) -> bool {
154	    path.contains("src/gen/")
155	        || path.ends_with(".ast.json")
156	        || path.ends_with(".ir.json")
157	        || path.ends_with(".manifest.json")
158	        || path.contains("/fixtures/semantic/")
159	}
160	
161	/// Deny direct edits to generated zones.
162	pub fn check_generated_zone_edit(path: &str) -> Result<(), ForgeError> {
163	    if is_generated_zone(path) {
164	        return Err(ForgeError::Input(format!(
165	            "generated_zone_direct_edit: direct edits to {path} are denied; use a spec or generator stage"
166	        )));
167	    }
168	    Ok(())
169	}
170	
171	// ── Projection ──
172	
173	/// Project a DomainModel into CALM and/or RDF via the DomainForge adapter.
174	/// Pure in-memory: no filesystem writes, no network, no CLI side effects (§10.4a).
175	pub fn project_model(
176	    model: &sea_forge_domainforge::DomainModel,
177	    kinds: &[ProjectionKind],
178	) -> Result<BTreeMap<ProjectionKind, BTreeMap<String, String>>, ForgeError> {
179	    let mut results = BTreeMap::new();
180	    for kind in kinds {
181	        let projected = sea_forge_domainforge::project(model, kind)?;
182	        results.insert(kind.clone(), projected);
183	    }
184	    Ok(results)
185	}
186	
187	/// Compute the rebuild_hash for a ProjectionRecord per §7.0b.
188	/// Hash of canonical {adapter_ref, domain_model_ref, source_refs, descriptor_sha256, input_hash, output_refs}.
189	pub fn compute_rebuild_hash(
190	    adapter_ref: &str,
191	    domain_model_ref: &serde_json::Value,
192	    source_refs: &[String],
193	    descriptor_sha256: &str,
194	    input_hash: &str,
195	    output_refs: &[StageFile],
196	) -> Result<String, ForgeError> {
197	    let canonical = serde_json::json!({
198	        "adapter_ref": adapter_ref,
199	        "domain_model_ref": domain_model_ref,
200	        "source_refs": source_refs,
201	        "descriptor_sha256": descriptor_sha256,
202	        "input_hash": input_hash,
203	        "output_refs": output_refs,
204	    });
205	    let bytes = serde_json::to_vec(&canonical)?;
206	    Ok(format!("sha256:{:x}", Sha256::digest(&bytes)))
207	}
208	
209	/// Build a ProjectionRecord from a successful projection.
210	#[allow(clippy::too_many_arguments)]
211	pub fn build_projection_record(
212	    projection_id: &str,
213	    kind: ProjectionKind,
214	    adapter_ref: &str,
215	    case_id: &str,
216	    run_id: &str,
217	    domain_model_ref: Option<&serde_json::Value>,
218	    source_refs: Vec<String>,
219	    input_hash: &str,
220	    outputs: &BTreeMap<String, String>,
221	    created_at: &str,
222	) -> Result<ProjectionRecord, ForgeError> {
223	    let mut output_refs = Vec::new();
224	    for (path, content) in outputs {
225	        let sha = format!("sha256:{:x}", Sha256::digest(content.as_bytes()));
226	        output_refs.push(StageFile {
227	            path: path.clone(),
228	            sha256: sha,
229	            generated: true,
230	        });
231	    }
232	    output_refs.sort_by(|a, b| a.path.cmp(&b.path));
233	
234	    let descriptor_sha256 = sea_forge_domainforge::ADAPTER_DESCRIPTOR_SHA256;
235	    let rebuild_hash = compute_rebuild_hash(
236	        adapter_ref,
237	        domain_model_ref.unwrap_or(&serde_json::Value::Null),
238	        &source_refs,
239	        descriptor_sha256,
240	        input_hash,
241	        &output_refs,
242	    )?;
243	
244	    Ok(ProjectionRecord {
245	        projection_id: projection_id.into(),
246	        projection_kind: kind,
247	        adapter_ref: adapter_ref.into(),
248	        case_id: case_id.into(),
249	        run_id: run_id.into(),
250	        domain_model_ref: domain_model_ref.cloned(),
251	        source_refs,
252	        input_hash: input_hash.into(),
253	        output_refs,
254	        quarantine_refs: vec![],
255	        validation: ProjectionValidation {
256	            status: ProjectionStatus::Accepted,
257	            validator_ref: descriptor_sha256.into(),
258	            basis: vec!["projection_validated".into()],
259	        },
260	        authority_refs: vec![],
261	        evidence_refs: vec![],
262	        settlement_ref: None,
263	        created_at: created_at.into(),
264	        rebuild_hash,
265	    })
266	}
267	
268	/// Process a pipeline run: validate ordering, quarantine failed stages,
269	/// compute classification.
270	pub fn process_pipeline(run: &mut SpecPipelineRun) -> Result<(), ForgeError> {
271	    validate_stage_order(&run.stages)?;
272	
273	    for stage in &mut run.stages {
274	        if stage.status == StageStatus::Rejected {
275	            quarantine_stage(stage, "stage_output_validation_failed")?;
276	        }
277	    }
278	
279	    run.proof_classification = compute_proof_classification(&run.stages);
280	    Ok(())
281	}
282	
283	// ── Regeneration determinism ──
284	
285	/// Verify that two sets of stage outputs are byte-identical.
286	/// Used to prove regeneration determinism (§10.7).
287	pub fn verify_byte_identity(a: &[StageFile], b: &[StageFile]) -> Result<bool, ForgeError> {
288	    if a.len() != b.len() {
289	        return Ok(false);
290	    }
291	    let mut a_sorted = a.to_vec();
292	    a_sorted.sort_by(|x, y| x.path.cmp(&y.path));
293	    let mut b_sorted = b.to_vec();
294	    b_sorted.sort_by(|x, y| x.path.cmp(&y.path));
295	    for (a_file, b_file) in a_sorted.iter().zip(b_sorted.iter()) {
296	        if a_file.path != b_file.path || a_file.sha256 != b_file.sha256 {
297	            return Ok(false);
298	        }
299	    }
300	    Ok(true)
301	}
302	
303	/// Hash file content for stage I/O records.
304	pub fn hash_content(content: &[u8]) -> String {
305	    format!("sha256:{:x}", Sha256::digest(content))
306	}
307	
308	/// Compute the input_hash for a projection (hash of all source file hashes).
309	pub fn compute_input_hash(source_refs: &[String]) -> Result<String, ForgeError> {
310	    let canonical = serde_json::json!({ "source_refs": source_refs });
311	    hash_canonical(&canonical)
312	}
