6	fn sha256_hex(bytes: &[u8]) -> String {
7	    format!("{:x}", Sha256::digest(bytes))
8	}
9	
10	fn source_file(uri: &str, content: &str) -> SourceFile {
11	    SourceFile {
12	        uri: uri.into(),
13	        sha256: sha256_hex(content.as_bytes()),
14	        content: content.into(),
15	    }
16	}
