18	const DEMO_SEA: &str = r#"@namespace "demo"
19	@version "1.0.0"
20	
21	Entity "Sample" in demo
22	Resource "Artifact" units in demo
23	Flow "Artifact" from "Sample" to "Sample" quantity 1
24	"#;
