33	fn make_stage(kind: StageKind, status: StageStatus) -> SpecPipelineStage {
34	    SpecPipelineStage {
35	        stage_id: format!("stage_{kind:?}").to_lowercase(),
36	        kind,
37	        inputs: vec![],
