46	fn make_stage_with_io(
47	    kind: StageKind,
48	    status: StageStatus,
49	    inputs: Vec<(&str, &str)>,
50	    outputs: Vec<(&str, &str)>,
51	) -> SpecPipelineStage {
52	    SpecPipelineStage {
53	        stage_id: format!("stage_{kind:?}").to_lowercase(),
54	        kind,
55	        inputs: inputs
56	            .iter()
57	            .map(|(p, h)| StageFile {
58	                path: p.to_string(),
59	                sha256: h.to_string(),
60	                generated: false,
61	            })
62	            .collect(),
63	        outputs: outputs
64	            .iter()
65	            .map(|(p, h)| StageFile {
66	                path: p.to_string(),
67	                sha256: h.to_string(),
68	                generated: true,
69	            })
70	            .collect(),
71	        command: None,
72	        status,
73	        quarantine_ref: None,
74	        settlement_basis: vec![],
75	    }
76	}
