78	// ── 1. Full pipeline hash-chain ──
79	
80	#[test]
81	fn pipeline_stages_hash_link_in_order() {
82	    let stages = vec![
83	        make_stage(StageKind::Adr, StageStatus::Accepted),
84	        make_stage(StageKind::Prd, StageStatus::Accepted),
85	        make_stage(StageKind::Sds, StageStatus::Accepted),
86	        make_stage(StageKind::Sea, StageStatus::Accepted),
87	    ];
88	    let chain_hash = compute_chain_hash(&stages).unwrap();
89	    assert!(chain_hash.starts_with("sha256:"));
90	
91	    // Touching one input byte of a stage changes the chain hash.
92	    let mut modified_stages = stages.clone();
93	    modified_stages[1].stage_id = "stage_prd_modified".into();
94	    let modified_hash = compute_chain_hash(&modified_stages).unwrap();
95	    assert_ne!(
96	        chain_hash, modified_hash,
97	        "changing a stage must change the chain hash"
98	    );
99	}
