119	// ── 3. Regeneration byte-identity ──
120	
121	#[test]
122	fn regeneration_produces_byte_identical_output() {
123	    let content = b"generated contract text";
124	    let hash = hash_content(content);
125	
126	    let stage1 = make_stage_with_io(
127	        StageKind::GeneratedContract,
128	        StageStatus::Accepted,
129	        vec![],
130	        vec![("contract.rs", &hash)],
131	    );
132	    let stage2 = make_stage_with_io(
133	        StageKind::GeneratedContract,
134	        StageStatus::Accepted,
135	        vec![],
136	        vec![("contract.rs", &hash)],
137	    );
138	    assert!(
139	        verify_byte_identity(&stage1.outputs, &stage2.outputs).unwrap(),
140	        "same content must produce byte-identical output"
141	    );
142	
143	    let different_hash = hash_content(b"different content");
144	    let stage3 = make_stage_with_io(
145	        StageKind::GeneratedContract,
146	        StageStatus::Accepted,
147	        vec![],
148	        vec![("contract.rs", &different_hash)],
149	    );
150	    assert!(
151	        !verify_byte_identity(&stage1.outputs, &stage3.outputs).unwrap(),
152	        "different content must fail byte-identity check"
153	    );
154	}
