157	
158	#[test]
159	fn classification_ceiling_prevents_above_generated_contract_without_last_mile() {
160	    // Generated contract accepted, but no last-mile/runtime/acceptance.
161	    let mut run = SpecPipelineRun {
162	        version: "0.1".into(),
163	        pipeline_id: "pipe_001".into(),
164	        case_id: "case_001".into(),
165	        run_id: "run_001".into(),
166	        context_id: Some("docs/specs/demo".into()),
167	        domain_model_ref: None,
168	        route: PipelineRoute::FullSpecToRuntime,
169	        authority_refs: vec![],
170	        evidence_refs: vec![],
171	        settlement_ref: None,
172	        stages: vec![
173	            make_stage(StageKind::Adr, StageStatus::Accepted),
174	            make_stage(StageKind::Prd, StageStatus::Accepted),
175	            make_stage(StageKind::Sds, StageStatus::Accepted),
176	            make_stage(StageKind::Sea, StageStatus::Accepted),
177	            make_stage(StageKind::Ast, StageStatus::Accepted),
178	            make_stage(StageKind::Ir, StageStatus::Accepted),
179	            make_stage(StageKind::Manifest, StageStatus::Accepted),
180	            make_stage(StageKind::GeneratedContract, StageStatus::Accepted),
181	        ],
182	        proof_classification: ProofClassification::AuthorityOnly,
183	    };
184	    process_pipeline(&mut run).unwrap();
185	    assert_eq!(
186	        run.proof_classification,
187	        ProofClassification::GeneratedContract,
188	        "classification must not exceed generated-contract without last-mile"
189	    );
190	
191	    // Add last-mile + runtime + acceptance → focused-slice.
192	    run.stages.push(make_stage(
193	        StageKind::LastMileAdapter,
194	        StageStatus::Accepted,
195	    ));
196	    run.stages
197	        .push(make_stage(StageKind::RuntimeWiring, StageStatus::Accepted));
198	    run.stages.push(make_stage(
199	        StageKind::AcceptanceProof,
200	        StageStatus::Accepted,
201	    ));
202	    process_pipeline(&mut run).unwrap();
203	    assert_eq!(
204	        run.proof_classification,
205	        ProofClassification::FocusedSlice,
206	        "classification reaches focused-slice with last-mile + runtime + acceptance"
207	    );
208	}
