212	#[test]
213	fn calm_and_rdf_projections_derive_from_same_domain_model_ref() {
214	    let model = load_validate(&demo_source_set()).unwrap();
215	    let kinds = vec![ProjectionKind::Calm, ProjectionKind::Rdf];
216	    let results = project_model(&model, &kinds).unwrap();
217	
218	    assert!(results.contains_key(&ProjectionKind::Calm));
