435	/// Rebuild the complete case projection from ordered case events.
436	pub fn replay_case(items: &[PlanItem], events: &[TraceEvent]) -> CaseProjection {
437	    let mut states = items
438	        .iter()
439	        .map(|item| ItemState::new(item.plan_item_id.clone()))
440	        .collect::<Vec<_>>();
441	    let item_map = items
442	        .iter()
443	        .map(|item| (item.plan_item_id.as_str(), item))
444	        .collect::<HashMap<_, _>>();
445	    let mut activation_sequence = Vec::new();
446	    let mut completed = false;
447	    let mut terminated_by = None;
448	    for event in events {
449	        let Some(item_id) = event.plan_item_id.as_deref() else {
450	            match event.kind {
451	                TraceKind::CaseClosed => completed = true,
452	                TraceKind::CaseTerminated => {
453	                    terminated_by = event
454	                        .payload
455	                        .get("blocking_item")
456	                        .and_then(serde_json::Value::as_str)
457	                        .map(str::to_owned)
458	                }
459	                _ => {}
460	            }
461	            continue;
462	        };
463	        let Some(state) = states.iter_mut().find(|state| state.item_id == item_id) else {
464	            continue;
465	        };
466	        match event.kind {
467	            TraceKind::ItemEnabled => state.status = ItemStatus::Enabled,
468	            TraceKind::ItemActivated => {
469	                state.status = ItemStatus::Active;
470	                state.instances += 1;
471	                activation_sequence.push(item_id.to_owned());
472	            }
473	            TraceKind::ItemCompleted | TraceKind::HumanTaskCompleted => {
474	                state.status = ItemStatus::Completed
475	            }
476	            TraceKind::ItemFailed => {
477	                state.failed_instances += 1;
478	                let repeats = item_map.get(item_id).is_some_and(|item| {
479	                    item.markers.repetition && state.instances < item.max_instances
480	                });
481	                state.status = if repeats {
482	                    ItemStatus::Available
483	                } else {
484	                    ItemStatus::Failed
485	                };
486	            }
487	            TraceKind::ItemTerminated => state.status = ItemStatus::Terminated,
488	            TraceKind::MilestoneAchieved => state.status = ItemStatus::Completed,
489	            _ => {}
490	        }
491	    }
492	    CaseProjection {
493	        items: states,
494	        activation_sequence,
495	        completed,
496	        terminated_by,
497	    }
498	}
499	
500	/// Determine the next deterministic case actions from persisted events alone.
501	pub fn next_case_actions(items: &[PlanItem], events: &[TraceEvent]) -> Vec<CaseAction> {
502	    let projection = replay_case(items, events);
503	    if projection.completed || projection.terminated_by.is_some() {
504	        return vec![];
505	    }
506	    if let Some(blocking_item) = required_item_failed(&projection.items, items) {
507	        return vec![CaseAction::TerminateCase { blocking_item }];
508	    }
509	    if can_auto_complete(&projection.items, items) {
510	        return vec![CaseAction::CompleteCase];
511	    }
512	    let workspace_files = derived_workspace_files(events);
513	    let mut actions = Vec::new();
514	    for item in items {
515	        let Some(state) = projection
516	            .items
517	            .iter()
518	            .find(|state| state.item_id == item.plan_item_id)
519	        else {
520	            continue;
521	        };
522	        if state.status != ItemStatus::Available
523	            || state.instances >= item.max_instances
524	            || !entry_criteria_satisfied(item, events, &workspace_files)
525	        {
526	            continue;
527	        }
528	        actions.push(if item.markers.manual_activation {
529	            CaseAction::Enable(item.plan_item_id.clone())
530	        } else {
531	            match item.item_kind {
532	                ItemKind::Milestone => CaseAction::AchieveMilestone(item.plan_item_id.clone()),
533	                ItemKind::HumanTask => CaseAction::ParkHumanTask(item.plan_item_id.clone()),
534	                _ => CaseAction::Activate(item.plan_item_id.clone()),
535	            }

