#[test]
fn debug_jail_sh_exec() {
    use sea_forge_core::types::{ExecutionRequest, Operation};
    use sea_forge_sandbox::{ExecutionSandbox, JailSandbox, NetworkPosture, SandboxSpec};
    use std::collections::BTreeMap;
    let root = tempfile::tempdir().unwrap();
    let workspace = root.path().join("workspace");
    let artifacts = root.path().join("artifacts");
    fs::create_dir_all(&workspace).unwrap();
    fs::create_dir_all(&artifacts).unwrap();
    let jail = JailSandbox;
    let spec = SandboxSpec {
        workspace_root: workspace.clone(),
        artifacts_root: artifacts.clone(),
        network: NetworkPosture::default(),
    };
    let handle = jail.prepare(&spec).unwrap();
    let mut env = BTreeMap::new();
    if let Ok(path) = std::env::var("PATH") {
        env.insert("PATH".into(), path);
    }
    env.insert("HOME".into(), "/tmp".into());
    let req = ExecutionRequest {
        plan_item_id: "item".into(),
        operation: Operation::ExecuteCommand {
            argv: vec!["sh".into(), "-c".into(), "exit 0".into()],
            cwd: ".".into(),
        },
        timeout_secs: 10,
        env,
        compensating_controls: vec![],
