    let result = jail.execute(&handle, &req).unwrap();
    eprintln!("DEBUG RESULT: {result:?}");
    if !result.stderr_path.is_empty() {
        if let Ok(content) = fs::read_to_string(&result.stderr_path) {
            eprintln!("DEBUG STDERR: {content}");
        }
    }
    let _ = jail.destroy(handle);
