265	pub fn execute(options: MigrateOptions<'_>) -> Result<u8, ForgeError> {
266	    if !options.root.is_dir() {
267	        return Err(ForgeError::Input(format!(
268	            "root does not exist: {}",
269	            options.root.display()
270	        )));
271	    }
272	    let root = options
273	        .root
274	        .canonicalize()
275	        .map_err(|e| ForgeError::io("canonicalize root", e))?;
276	    ensure_not_migrated(&root)?;
277	
278	    let (key_dir, key_id) = resolve_key_config(&options)?;
279	    let signing_key = load_or_create_signing_key(&key_dir, &key_id)?;
280	
281	    let run_to_case = read_case_mapping(&root)?;
282	    let files = enumerate_files(&root, Path::new("."))?;
283	
284	    let mut entries: Vec<(String, LegacyImportPayload)> = Vec::new();
285	    for file in &files {
286	        let rel = file
287	            .strip_prefix(&root)
288	            .map_err(|_| ForgeError::Internal("file escaped root".into()))?;
289	        let rel_str = rel
290	            .to_str()
291	            .ok_or_else(|| ForgeError::Input("non-utf8 relative path".into()))?;
292	        // Skip files that are part of the ledger itself or migration marker.
293	        if rel_str == "migration.json"
294	            || rel_str.starts_with("ledgers/")
295	            || rel_str.starts_with("quarantine/")
296	            || rel_str.starts_with("authority/")
297	            || rel_str == "capabilities.jsonl"
298	        {
299	            continue;
300	        }
301	        let target = target_path_for(rel_str, &run_to_case)?;
302	        let size_bytes = fs::metadata(file)
303	            .map_err(|e| ForgeError::io(format!("metadata {}", file.display()), e))?
304	            .len();
305	        let sha256 = sha256_file_with_prefix(file)?;
306	        entries.push((
307	            rel_str.to_string(),
308	            LegacyImportPayload {
309	                path: target,
310	                sha256,
311	                size_bytes,
312	                legacy_record_version: LEGACY_RECORD_VERSION.into(),
313	            },
314	        ));
315	    }
316	
317	    let manager = LedgerManager::new(&root)?;
318	    let stream = manager.open_stream(MIGRATION_STREAM, "sea-forge-migrate")?;
319	    let mut committed = Vec::new();
320	    for (original, payload) in &entries {
321	        let refs = subject_refs_for(original);
322	        let record = stream.commit_typed("legacy_import", refs, payload, vec![])?;
323	        committed.push(record);
324	    }
325	
326	    let global_checkpoint = manager.create_global_checkpoint(&signing_key, &key_id)?;
327	    manager.verify_global_checkpoints(&signing_key.verifying_key())?;
328	
329	    // Move files to their v0.2 case layout destinations.
330	    for (original, payload) in &entries {
331	        let src = root.join(original);
332	        let dst = root.join(&payload.path);
333	        move_file_atomicish(&src, &dst)?;
334	    }
335	
336	    // Create empty case-level event logs for each migrated case.
337	    for case_id in run_to_case
338	        .values()
339	        .collect::<std::collections::BTreeSet<_>>()
340	    {
341	        let events_path = root.join("cases").join(case_id).join("case-events.jsonl");
342	        if !events_path.exists() {
343	            fs::write(&events_path, b"")
344	                .map_err(|e| ForgeError::io(format!("write {}", events_path.display()), e))?;
345	        }
346	    }
347	
348	    // Remove the now-empty v0.1 run directories.
349	    remove_empty_run_dirs(&root)?;
350	
351	    // Write the migration marker only after all prior steps succeeded.
352	    let marker = MigrationMarker {
353	        version: sea_forge_core::RECORD_VERSION.into(),
354	        migrated_at: chrono::Utc::now().to_rfc3339(),
355	        stream_id: MIGRATION_STREAM.into(),
356	        entry_count: committed.len() as u64,
357	        global_checkpoint_hash: global_checkpoint.global_checkpoint_hash,
358	    };
359	    fs::write(
360	        migration_marker_path(&root),
361	        serde_json::to_vec_pretty(&marker).map_err(|e| ForgeError::Serialization(e.to_string()))?,
362	    )
363	    .map_err(|e| ForgeError::io("write migration marker", e))?;
364	
365	    println!("migrated {} legacy files", committed.len());
366	    println!("stream={}", MIGRATION_STREAM);
367	    println!("checkpoint_hash={}", marker.global_checkpoint_hash);
368	    Ok(0)
369	}
